CREATE TABLE IF NOT EXISTS hr_candidate_offers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), candidate_wix_id text NOT NULL, display_name text NOT NULL, job_role text NOT NULL, city text NOT NULL, work_type text NOT NULL CHECK(work_type IN ('SHIFT','PART_TIME','FULL_TIME')), experience_years integer CHECK(experience_years BETWEEN 0 AND 60), available_from date, description text NOT NULL, status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','APPROVED','REJECTED','WITHDRAWN')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS hr_candidate_offers_status_date_idx ON hr_candidate_offers(status,created_at DESC);
CREATE INDEX IF NOT EXISTS hr_candidate_offers_owner_idx ON hr_candidate_offers(candidate_wix_id,created_at DESC);
CREATE TABLE IF NOT EXISTS hr_candidate_offer_interests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), offer_id uuid NOT NULL REFERENCES hr_candidate_offers(id), recruiter_wix_id text NOT NULL, recruiter_request_id uuid NOT NULL REFERENCES hr_recruiter_requests(id), message text NOT NULL, status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','APPROVED','REJECTED','ACCEPTED','DECLINED')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(offer_id,recruiter_request_id));
CREATE INDEX IF NOT EXISTS hr_candidate_interests_recruiter_idx ON hr_candidate_offer_interests(recruiter_wix_id,created_at DESC);
